// replaycast: a podcast-style player for Claude's replies.
//
// A Listen button under each reply, and a now-playing bar above the prompt with
// a progress bar, play/pause, ±10 s, previous/next sentence, speed 1x-4x and voice.
//
// Two engines, both fully offline:
//   native   Windows. engine/reader.py synthesizes with the Windows voice (SAPI)
//            or a local Piper model, time-stretches with ffmpeg (atempo keeps the
//            pitch) and plays through Windows MCI. Seek, speed and voice switching.
//   builtin  Any platform. Claude Code's own $.audio.speak, one sentence at a time.
//            Play/pause and sentence skipping; speed is the system voice's own.
// No network calls. Nothing leaves the machine.

const ACCENT = '#D97757'
const SPEEDS = [1, 1.25, 1.5, 1.75, 2, 2.25, 2.5, 2.75, 3, 3.25, 3.5, 3.75, 4]
const CHARS_PER_SEC = 13 // rough listening rate at 1x, for estimates

// Resolved once from userConfig and the environment
let cfg = null
// 'native' | 'builtin'
let engine = null
let stateDir = ''

let speed = 1.5
let voice = 'sapi'
let autoRead = false
let lastAnswer = ''

// The reply being played: { id, text, title }
let active = null
// Player state, from the native engine's state.json or the builtin loop
let st = null
let child = null
let poller = null
let lastSig = ''

// Builtin engine: sentence spans and a token that invalidates stale loops
let spans = []
let cursor = 0
let token = 0

export function label(s) {
  return s + 'x'
}

export function clock(ms) {
  const t = Math.max(0, Math.round((ms || 0) / 1000))
  return Math.floor(t / 60) + ':' + String(t % 60).padStart(2, '0')
}

function estimate(text, s) {
  return clock((speakable(text).length / CHARS_PER_SEC / s) * 1000)
}

// Turn markdown into something that sounds right when spoken
export function speakable(md) {
  return String(md || '')
    .replace(/```[\s\S]*?```/g, ' (code block skipped.) ')
    .replace(/`([^`]*)`/g, '$1')
    .replace(/!\[[^\]]*\]\([^)]*\)/g, '')
    .replace(/\[([^\]]+)\]\([^)]*\)/g, '$1')
    .replace(/^\s*\|?[\s:|-]+\|[\s:|-]*$/gm, '')
    .replace(/^\s*\|/gm, '')
    .replace(/\|\s*$/gm, '.')
    .replace(/\|/g, ', ')
    .replace(/^#{1,6}\s*(.*)$/gm, '$1.')
    .replace(/^\s*(?:[-*•]|\d+\.)\s+(.*)$/gm, '$1.')
    .replace(/[*_~>#]+/g, '')
    .replace(/[→⇒]/g, ' to ')
    .replace(/[★✓✗☐●○■▶⏸]/g, '')
    .replace(/\.(\s*\.)+/g, '.')
    .replace(/[^\S\n]+/g, ' ')
    .replace(/\n{2,}/g, '\n')
    .trim()
}

// Sentence spans [start, end) for the builtin engine, each under 400 characters
export function sentences(text) {
  const out = []
  const re = /[^.!?;:\n]+(?:[.!?;:]+|\n|$)/g
  let m
  while ((m = re.exec(text)) !== null) {
    if (!m[0].trim()) continue
    let s = m.index
    const e = m.index + m[0].length
    while (e - s > 400) {
      const cut = text.lastIndexOf(' ', s + 400)
      const at = cut > s ? cut : s + 400
      out.push([s, at])
      s = at
    }
    out.push([s, e])
  }
  return out
}

function titleOf(text) {
  const first = speakable(text).split('\n').find((l) => l.trim().length > 0) || 'Claude reply'
  return first.length > 64 ? first.slice(0, 61) + '…' : first
}

function barSvg(frac, w) {
  const x = Math.round(Math.max(0, Math.min(1, frac)) * w)
  const knob = Math.max(6, Math.min(w - 6, x))
  return (
    '<svg xmlns="http://www.w3.org/2000/svg" width="' + w + '" height="14" viewBox="0 0 ' + w + ' 14">' +
    '<rect x="0" y="5" width="' + w + '" height="4" rx="2" fill="rgba(128,128,128,0.35)"/>' +
    '<rect x="0" y="5" width="' + x + '" height="4" rx="2" fill="' + ACCENT + '"/>' +
    '<circle cx="' + knob + '" cy="7" r="6" fill="' + ACCENT + '"/></svg>'
  )
}

function barText(frac, w) {
  const x = Math.round(Math.max(0, Math.min(1, frac)) * w)
  return '━'.repeat(x) + '●' + '─'.repeat(Math.max(0, w - x))
}

// ---------- configuration ----------

async function resolveEngine($) {
  if (engine) return engine
  const isWindows = (await $.env.get('OS')) === 'Windows_NT'
  const want = cfg.engine || 'auto'
  engine = want === 'builtin' || (want === 'auto' && !isWindows) ? 'builtin' : 'native'
  if (engine === 'native' && !isWindows) {
    $.ui.toast('replaycast: the native engine is Windows-only; using the built-in voice')
    engine = 'builtin'
  }
  if (engine === 'native') {
    const base = (await $.env.get('LOCALAPPDATA')) || $.plugin.root
    stateDir = String(base).replace(/\\/g, '/') + '/replaycast'
  }
  return engine
}

function voices() {
  if (engine === 'builtin') return [{ value: 'system', label: cfg.builtin_voice || 'System voice' }]
  const list = [{ value: 'sapi', label: (cfg.sapi_voice || 'Windows voice') + ' · offline' }]
  if (cfg.piper && cfg.piper_model) list.unshift({ value: 'piper', label: 'Piper neural · offline' })
  return list
}

function voiceName(v) {
  const hit = voices().find((x) => x.value === v)
  return hit ? hit.label.split(' · ')[0] : v
}

// ---------- native engine (Windows) ----------

async function sendCmd($, line) {
  if (engine === 'builtin') return builtinCmd($, line)
  try {
    const path = stateDir + '/cmd.txt'
    const prev = (await $.fs.exists(path)) ? String(await $.fs.read(path)) : ''
    await $.fs.write(path, prev + line + '\n')
  } catch (err) {
    $.ui.toast('replaycast: could not send ' + line)
  }
}

async function readState($) {
  try {
    return JSON.parse(String(await $.fs.read(stateDir + '/state.json')))
  } catch (err) {
    return null
  }
}

function engineArgs(extra) {
  const argv = [
    cfg.python || 'pythonw', $root + '/engine/reader.py',
    '--state', stateDir,
    '--voice', voice,
    '--speed', String(speed),
    '--ffmpeg', cfg.ffmpeg || 'ffmpeg',
  ]
  if (cfg.sapi_voice) argv.push('--sapi-voice', cfg.sapi_voice)
  if (cfg.piper && cfg.piper_model) argv.push('--piper', cfg.piper, '--piper-model', cfg.piper_model)
  return argv.concat(extra)
}

// The plugin directory, captured from $.plugin.root on first use
let $root = ''

function runNative($, offset) {
  $root = $.plugin.root.replace(/\\/g, '/')
  const stream = $.process.spawn({
    argv: engineArgs(['--text', stateDir + '/text.txt', '--offset', String(offset || 0)]),
    cwd: $root,
  })
  child = stream
  void (async () => {
    try {
      for await (const piece of stream) {
        if (piece && piece.stream === 'stderr' && piece.text) $.ui.log('replaycast: ' + piece.text, { to: 'debug' })
      }
    } catch (err) {
      // No Python, or the engine crashed before it started: fall back to the built-in voice
      if (child === stream && st && st.status === 'loading') {
        $.ui.toast('replaycast: the Windows engine could not start (' + err.message + '); using the built-in voice')
        engine = 'builtin'
        voice = 'system'
        child = null
        if (active) await play($, active.id, active.text, 0)
        return
      }
    }
    if (child === stream) child = null
  })()
}

async function killNative($) {
  const old = child
  child = null
  if (!old) return
  await sendCmd($, 'stop')
  if (typeof old.return === 'function') {
    try {
      await old.return()
    } catch (err) {
      // already gone
    }
  }
}

// Fill the audio cache for a fresh reply so Listen starts at once (Piper only; SAPI is instant)
async function prefetch($, text) {
  if (engine !== 'native' || voice !== 'piper') return
  const clean = speakable(text)
  if (!clean) return
  try {
    await $.fs.write(stateDir + '/prefetch.txt', clean)
  } catch (err) {
    return
  }
  $root = $.plugin.root.replace(/\\/g, '/')
  const stream = $.process.spawn({ argv: engineArgs(['--prefetch', '--text', stateDir + '/prefetch.txt']), cwd: $root })
  void (async () => {
    try {
      for await (const piece of stream) void piece
    } catch (err) {
      // a failed prefetch only costs the first-play wait
    }
  })()
}

function startPolling($) {
  if (poller) poller.cancel()
  poller = $.clock.every(300, async () => {
    const next = await readState($)
    if (next && engine === 'native') st = next
    const sig = st ? [st.status, st.paused, Math.round((st.elapsedMs || 0) / 250), st.totalMs, st.speed, st.voice].join('|') : ''
    if (sig !== lastSig) {
      lastSig = sig
      $.ui.invalidate('ui.render')
    }
    if (st && (st.status === 'done' || st.status === 'stopped' || st.status === 'error') && !child) {
      if (poller) poller.cancel()
      poller = null
    }
  })
}

// ---------- builtin engine (any platform) ----------

function builtinState(status) {
  const text = active ? speakable(active.text) : ''
  const before = cursor < spans.length ? spans[cursor][0] : text.length
  st = {
    status,
    paused: status === 'paused',
    elapsedMs: (before / CHARS_PER_SEC) * 1000,
    totalMs: (text.length / CHARS_PER_SEC) * 1000,
    speed: 1,
    voice: 'system',
    engine: 'builtin',
    charPos: before,
  }
}

async function builtinLoop($) {
  const mine = ++token
  const text = speakable(active.text)
  builtinState('playing')
  $.ui.invalidate('ui.render')
  while (mine === token && cursor < spans.length) {
    const at = cursor
    const [s, e] = spans[at]
    try {
      await $.audio.speak(text.slice(s, e).trim(), cfg.builtin_voice ? { voice: cfg.builtin_voice } : undefined)
    } catch (err) {
      if (mine === token) {
        builtinState('error')
        st.lastError = err.message
        $.ui.toast('replaycast: the system voice failed (' + err.message + ')')
        $.ui.invalidate('ui.render')
      }
      return
    }
    if (mine !== token) return
    // A prev/next during the sentence already moved the cursor
    if (cursor === at) cursor = at + 1
    builtinState(cursor < spans.length ? 'playing' : 'done')
    $.ui.invalidate('ui.render')
  }
}

async function builtinCmd($, line) {
  const [cmd, arg] = line.split(' ')
  if (cmd === 'stop') {
    token++
    return
  }
  if (cmd === 'toggle') {
    if (st && st.status === 'paused') {
      void builtinLoop($)
    } else {
      // The sentence being spoken finishes; nothing after it starts
      token++
      builtinState('paused')
    }
  } else if (cmd === 'next') {
    cursor = Math.min(spans.length - 1, cursor + 1)
  } else if (cmd === 'prev') {
    cursor = Math.max(0, cursor - 1)
  } else if (cmd === 'back' || cmd === 'fwd') {
    // About one sentence per 10 s step at 1x
    const step = Math.max(1, Math.round(Number(arg || 10) / 10))
    cursor = Math.max(0, Math.min(spans.length - 1, cursor + (cmd === 'back' ? -step : step)))
  }
  if ((cmd === 'next' || cmd === 'prev' || cmd === 'back' || cmd === 'fwd') && st && st.status !== 'paused') {
    builtinState('playing')
  }
  $.ui.invalidate('ui.render')
}

// ---------- shared player ----------

async function play($, id, text, offset) {
  await resolveEngine($)
  const clean = speakable(text)
  if (!clean) {
    $.ui.toast('Nothing to read in this reply')
    return
  }
  await stopAll($)
  if (!voices().some((x) => x.value === voice)) voice = voices()[0].value
  active = { id, text, title: titleOf(text) }
  if (engine === 'builtin') {
    spans = sentences(clean)
    cursor = Math.max(0, spans.findIndex((sp) => sp[1] > (offset || 0)))
    void builtinLoop($)
    return
  }
  try {
    await $.fs.write(stateDir + '/cmd.txt', '')
    await $.fs.write(stateDir + '/text.txt', clean)
  } catch (err) {
    $.ui.toast('replaycast: could not write to ' + stateDir)
    active = null
    return
  }
  st = { status: 'loading', paused: false, elapsedMs: 0, totalMs: 0, speed, voice }
  runNative($, offset || 0)
  startPolling($)
  $.ui.invalidate('ui.render')
}

async function stopAll($) {
  if (engine === 'builtin') token++
  else await killNative($)
}

async function togglePause($) {
  if (!st) return
  if (engine === 'native') {
    st = { ...st, paused: !st.paused, status: st.status === 'loading' ? 'loading' : st.paused ? 'playing' : 'paused' }
  }
  await sendCmd($, 'toggle')
  $.ui.invalidate('ui.render')
}

async function close($) {
  await stopAll($)
  active = null
  st = null
  if (poller) poller.cancel()
  poller = null
  $.ui.invalidate('ui.render')
}

async function setSpeed($, s) {
  speed = s
  await $.store.set('speed', s)
  if (active && child) {
    await sendCmd($, 'speed ' + s)
    if (st) st = { ...st, speed: s }
  }
  $.ui.invalidate('ui.render')
}

async function setVoice($, v) {
  voice = v
  await $.store.set('voice', v)
  // A new voice needs new audio: restart from where we are
  if (active && st && st.status !== 'done') {
    await play($, active.id, active.text, st.charPos || 0)
  } else {
    $.ui.invalidate('ui.render')
  }
}

async function replay($) {
  if (active) await play($, active.id, active.text, 0)
}

// ---------- hooks ----------

export function register(on, options) {
  cfg = options || {}
  if (typeof cfg.default_speed === 'number') speed = Math.max(1, Math.min(4, cfg.default_speed))

  on('session.start', async ($, e, next) => {
    await resolveEngine($)
    const s = await $.store.get('speed')
    if (typeof s === 'number' && s >= 1 && s <= 4) speed = s
    const v = await $.store.get('voice')
    if (typeof v === 'string' && voices().some((x) => x.value === v)) voice = v
    else voice = voices()[0].value
    autoRead = (await $.store.get('autoRead')) === true
    try {
      await $.command.register({ name: 'listen', description: 'Listen to the last Claude reply' })
      await $.command.register({ name: 'listen-speed', description: 'Set listening speed, 1 to 4', argumentHint: '[1-4]' })
      await $.command.register({ name: 'listen-pause', description: 'Pause or resume listening' })
      await $.command.register({ name: 'listen-stop', description: 'Stop listening and close the player' })
      await $.command.register({ name: 'listen-auto', description: 'Toggle listening to each new reply automatically' })
    } catch (err) {
      $.ui.log('replaycast: could not register a command: ' + err.message)
    }
    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    if (!e.agentId && !e.isAborted && e.answer) {
      lastAnswer = e.answer
      if (autoRead) await play($, 'last', e.answer, 0)
      else await prefetch($, e.answer)
    }
    return next(e)
  })

  on('command.run', { command: 'listen' }, async ($) => {
    if (!lastAnswer) return { text: 'No reply yet in this session. Use Listen under a reply.' }
    await play($, 'last', lastAnswer, 0)
    return {}
  })

  on('command.run', { command: 'listen-speed' }, async ($, e) => {
    const v = parseFloat(String(e.args || '').replace('x', ''))
    if (!(v >= 1 && v <= 4)) return { text: 'Speed is ' + label(speed) + '. Use /listen-speed 1 to /listen-speed 4.' }
    await setSpeed($, Math.round(v * 4) / 4)
    return { text: 'Speed ' + label(speed) }
  })

  on('command.run', { command: 'listen-pause' }, async ($) => {
    if (!active) return { text: 'Nothing is playing' }
    await togglePause($)
    return {}
  })

  on('command.run', { command: 'listen-stop' }, async ($) => {
    await close($)
    return {}
  })

  on('command.run', { command: 'listen-auto' }, async ($) => {
    autoRead = !autoRead
    await $.store.set('autoRead', autoRead)
    return { text: 'Auto-listen is ' + (autoRead ? 'on' : 'off') }
  })

  // Under each reply: Listen, with how long it takes at the current speed
  on('ui.render', { component: 'AssistantMessage' }, async ($, e, next) => {
    const theirs = await next(e)
    const text = e.props && typeof e.props.text === 'string' ? e.props.text : ''
    if (speakable(text).length < 2) return theirs
    const { Box, Button, Text } = $.ui.resolve(e)
    const id = e.requestId
    const isThis = active && active.id === id
    const pace = engine === 'builtin' ? 1 : speed
    const row = isThis
      ? [
          Button({
            key: 'rc-row-toggle-' + id,
            label: st && st.paused ? '▶  Resume' : '⏸  Pause',
            variant: 'secondary',
            onPress: async () => { await togglePause($) },
          }),
          Text({ dimColor: true, children: [st && st.status === 'loading' ? 'Preparing audio…' : 'Now playing'] }),
        ]
      : [
          Button({
            key: 'rc-listen-' + id,
            label: '▶  Listen',
            variant: 'secondary',
            onPress: async () => { await play($, id, text, 0) },
          }),
          Text({ dimColor: true, children: [estimate(text, pace) + ' at ' + label(pace)] }),
        ]
    return Box({
      flexDirection: 'column',
      children: [theirs, Box({ flexDirection: 'row', columnGap: 1, alignItems: 'center', children: row })],
    })
  })

  // The now-playing bar above the prompt
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (!active) return next(e)
    const { Box, Text, Button, Select, Svg } = $.ui.resolve(e)
    const desktop = e.surface === 'desktop'
    const native = engine === 'native'
    const s = st || {}
    const loading = s.status === 'loading'
    const finished = s.status === 'done' || s.status === 'stopped'
    const frac = s.totalMs ? (s.elapsedMs || 0) / s.totalMs : 0
    const paused = !!s.paused

    const status = s.status === 'error'
      ? 'Could not make audio' + (s.lastError ? ': ' + String(s.lastError).slice(0, 80) : '')
      : loading
        ? 'Preparing audio…'
        : finished
          ? 'Finished'
          : (paused ? 'Paused' : 'Playing') + ' · ' + voiceName(s.voice || voice) +
            (native && s.engine === 'sapi' && voice === 'piper' ? ' (fallback)' : '')

    const header = Box({
      flexDirection: 'row',
      columnGap: 1,
      children: [
        Text({ color: ACCENT, bold: true, children: ['🎧'] }),
        Text({ bold: true, wrap: 'truncate-end', children: [active.title] }),
      ],
    })

    const progress = Box({
      flexDirection: 'row',
      columnGap: 1,
      alignItems: 'center',
      children: [
        Text({ dimColor: true, children: [clock(s.elapsedMs)] }),
        desktop
          ? Svg({ source: barSvg(frac, 420), alt: Math.round(frac * 100) + '% played', width: 420, height: 14 })
          : Text({ color: ACCENT, children: [barText(frac, 30)] }),
        Text({ dimColor: true, children: [clock(s.totalMs)] }),
        Text({ dimColor: true, children: ['· ' + status] }),
      ],
    })

    const controls = [
      Button({ key: 'rc-prev', label: '⏮', plain: true, onPress: async () => { await sendCmd($, 'prev') } }),
      Button({ key: 'rc-back', label: '↺ 10', plain: true, onPress: async () => { await sendCmd($, 'back 10') } }),
      finished
        ? Button({ key: 'rc-replay', label: '↻  Replay', variant: 'primary', onPress: async () => { await replay($) } })
        : Button({
            key: 'rc-toggle',
            label: paused ? '▶  Play' : '⏸  Pause',
            variant: 'primary',
            onPress: async () => { await togglePause($) },
          }),
      Button({ key: 'rc-fwd', label: '10 ↻', plain: true, onPress: async () => { await sendCmd($, 'fwd 10') } }),
      Button({ key: 'rc-next', label: '⏭', plain: true, onPress: async () => { await sendCmd($, 'next') } }),
    ]
    if (native) {
      controls.push(
        Select({
          key: 'rc-speed',
          label: 'Speed',
          value: String(speed),
          options: SPEEDS.map((x) => ({ value: String(x), label: label(x) })),
          onSelect: async (v) => { await setSpeed($, parseFloat(v)) },
        }),
      )
    }
    if (voices().length > 1) {
      controls.push(
        Select({
          key: 'rc-voice',
          label: 'Voice',
          value: voice,
          options: voices(),
          onSelect: async (v) => { await setVoice($, v) },
        }),
      )
    }
    controls.push(Button({ key: 'rc-close', label: 'Close player', role: 'dismiss', onPress: async () => { await close($) } }))

    return Box({
      flexDirection: 'column',
      rowGap: 0,
      paddingX: 1,
      borderStyle: 'round',
      borderColor: ACCENT,
      children: [header, progress, Box({ flexDirection: 'row', columnGap: 1, alignItems: 'center', children: controls })],
    })
  })
}
